# Xbox port item 10b: route RealmObjectExtensions.Detach / CopyChangesToRealm to the hand-written RealmDetacher (AutoMapper fails under Native AOT).
# RealmDetacher.cs (osu.Game\Database) must exist; it is not generated by this script.
$f = 'D:\osu-xbox-scratch\osu-aot\osu.Game\Database\RealmObjectExtensions.cs'
if (-not (Test-Path "$f.orig")) { Copy-Item $f "$f.orig" }
$t = [IO.File]::ReadAllText("$f.orig")
$t = $t -replace "`r`n", "`n"

$start = $t.IndexOf('        private static readonly IMapper write_mapper')
$marker = "        /// <summary>`n        /// Create a detached copy of the each item in the collection."
$end = $t.IndexOf($marker)
if ($start -lt 0 -or $end -lt 0) { throw "markers not found ($start, $end)" }
$t = $t.Remove($start, $end - $start)

$t = $t.Replace("            if (item is BeatmapSetInfo)`n                return beatmap_set_mapper.Map<T>(item);`n`n            return mapper.Map<T>(item);", "            return RealmDetacher.Detach(item);")
$t = $t.Replace("            => write_mapper.Map(source, destination);", "            => RealmDetacher.CopyChangesToRealm(source, destination);")
if ($t -match 'write_mapper|beatmap_set_mapper|mapper\.Map') { throw "mapper references remain" }
[IO.File]::WriteAllText($f, $t)
"patched; lines: " + ($t -split "`n").Count

